using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json.Linq;
public static class LabIdentityCapture {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-09_B4_LabIdentity/";
 public static void Shot(string n,Vector3 p,Vector3 to,float fov=82){var g=new GameObject("LabReviewCamera"){hideFlags=HideFlags.HideAndDontSave};var c=g.AddComponent<Camera>();c.transform.position=p;c.transform.LookAt(to);c.fieldOfView=fov;c.nearClipPlane=.04f;c.farClipPlane=250;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,1000,24){antiAliasing=4};var prev=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,1000),0,0);tex.Apply();File.WriteAllBytes(O+n+".png",tex.EncodeToPNG());}finally{RenderTexture.active=prev;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
 public static object Before()=>Run("before");public static object After()=>Run("after");
 public static object Details(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).ToArray();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player.SetActive(false);int count=0;try{
 foreach(string n in new[]{"B4_E03_ElectrodePrepBench_02","B4_E02_ElectronicsBench_03","B4_E02_TestChamberBench_05","B4_E02_MetrologyIsland","B4_E02_SensorPrepBench_07","B4_C04_AnalysisBench_01","B4_C03_SensorWorkbench_01","B4_C02_VitalCart_02","B4_C03_CalibrationRack_03","B4_C01_PrecisionPlatform_01","B4_W01_AdaptiveTargetArray_02","B4_W02_TrajectoryGantry_01","B4_S01_LoadResistanceRig_01","B4_E02_ProtocolTable_01"}){var t=ts.Single(t=>t.name==n);var b=t.GetComponent<MeshFilter>().sharedMesh.bounds;float z=b.max.z+Mathf.Max(.70f,b.size.x*.43f);Shot("detail_"+n,t.TransformPoint(new Vector3(.18f,1.67f,z)),t.TransformPoint(new Vector3(0,Mathf.Min(1.25f,b.center.y+.18f),0)),78);count++;}
 var e=ts.Single(t=>t.name=="B4_E03_ElectrodePrepBench_02");Shot("close_E03_electrodes",e.TransformPoint(new Vector3(-.20f,1.57f,.70f)),e.TransformPoint(new Vector3(-.22f,1.04f,.02f)),72);Shot("close_E03_record",e.TransformPoint(new Vector3(-.79f,1.43f,.52f)),e.TransformPoint(new Vector3(-.79f,.925f,.20f)),51);
 var d=ts.Single(t=>t.name=="B4_E02_ProtocolTable_01");Shot("close_E02_record",d.TransformPoint(new Vector3(.93f,1.53f,.67f)),d.TransformPoint(new Vector3(.93f,.944f,.21f)),48);Shot("close_E02_keyboard",d.TransformPoint(new Vector3(0,1.45f,.78f)),d.TransformPoint(new Vector3(0,1.0f,.05f)),64);Shot("close_E02_rear",d.TransformPoint(new Vector3(-.59f,1.32f,-1.05f)),d.TransformPoint(new Vector3(-.49f,1.0f,-.51f)),75);count+=5;
 }finally{EditorSceneManager.OpenScene(s.path);}return new{images=count};}
 static object Run(string phase){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");int count=0;var plan=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B4_LayoutPolish/layout.json"));var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player.SetActive(false);try{foreach(var r in plan["rooms"].Where(r=>(string)r["kind"]!="core")){string code=(string)r["id"];var center=new Vector3((float)r["x"],-66,-(float)r["v"]);var d=r["doors"][0];var dir=new Vector3((float)d["x"],0,(float)d["z"]).normalized;Shot(phase+"_"+code,center+dir*((float)r["r"]-1.3f)+Vector3.up*1.7f,center+Vector3.up*1.1f,90);Shot(phase+"_"+code+"_overview",center-dir*((float)r["r"]*.57f)+Vector3.up*3.3f,center+dir*((float)r["r"]*.12f)+Vector3.up*.9f,94);count+=2;}}finally{EditorSceneManager.OpenScene(s.path);}return new{phase,images=count};}
}
